const BASE = '{{WA_API_BASE}}/api/v1';
const headers = {
  'Authorization': 'Bearer ' + process.env.SM_API_KEY, // sm_live_your_api_key
  'Content-Type': 'application/json',
};

// Open, unassigned chats (newest activity first)
const list = await fetch(BASE + '/conversations?status=open&assignedToUserId=unassigned&limit=25', { headers });
const { data } = await list.json();

for (const conv of data.items) {
  // Hand each one to a teammate; null would put it back in the queue
  const res = await fetch(BASE + '/conversations/' + conv.id, {
    method: 'PATCH',
    headers,
    body: JSON.stringify({ assignedToUserId: '5b1d9e2c-7a3f-4c8e-b6d1-2f4a8c9e0b7d' }),
  });
  const { data: updated } = await res.json();
  console.log(updated.id, updated.assignedToUserId, updated.windowOpen);
}
